//
// data/dictionary.tsv compiled into the library (header generated by
// cmake/embed.cmake).
//
// The file goes in as text and is parsed at startup, which costs about a
// megabyte of binary and a few milliseconds. A packed form would be a third
// of the size; it is not here yet because the optional extension pack needs
// a packed, memory-mappable layout anyway, and building two formats before
// the first one has proven itself would be wasted work. The loader behind
// this function is the only thing that would have to change.
#include "dict/word_data.h"

#include "zcode_data_dictionary.h"

namespace zcode::dict {

std::string_view embedded_word_list() {
    // The generated array carries one trailing NUL that is not part of the
    // file.
    return std::string_view(reinterpret_cast<const char*>(zcode_data_dictionary),
                            sizeof zcode_data_dictionary - 1);
}

}  // namespace zcode::dict
